import './design-printer.js?v=design-device-1';
const store=window.PopomoDesigns,root=document.querySelector('#works-list');
let language='en',models=[],timer;
try{language=localStorage.getItem('popomo-language')==='zh'?'zh':'en';}catch{}
const t=(zh,en)=>language==='en'?en:zh;
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(zh,en){const toast=document.querySelector('#works-toast');toast.textContent=t(zh,en);toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2500);}
function cover(design){if(design.cover)return `<div class="works-cover"><img class="works-render" src="${escape(design.cover)}" alt="${escape(design.name)}"></div>`;const model=models.find(m=>m.name===design.model);if(!model)return `<div class="works-cover"><img class="works-render" src="${escape(design.image)}" alt="${escape(design.name)}"></div>`;return `<div class="works-cover"><div class="works-case" style="aspect-ratio:${model.width/model.height}"><div class="works-case-mask" style="mask-image:url('${model.mask}');-webkit-mask-image:url('${model.mask}')"><div class="works-case-photo" style="background-image:url('${escape(design.image)}');background-position:50% ${Number(design.position??50)}%;transform:scale(${Number(design.zoom||100)/100})"></div></div><img src="${model.overlay}" alt="${escape(design.name)}"></div></div>`;}
function render(){document.documentElement.lang=language==='en'?'en':'zh-CN';document.title=t('POPOMO · 我的设计','POPOMO · My designs');document.querySelector('#flow-language').value=language;document.querySelectorAll('[data-zh]').forEach(el=>el.textContent=el.dataset[language==='en'?'en':'zh']);const designs=store.list();document.querySelector('#works-total').textContent=t(`共 ${designs.length} 件作品`,`${designs.length} designs`);root.innerHTML=designs.length?designs.map(design=>`<article class="works-card"><a class="works-cover-frame works-detail-link" href="./work-detail.html?id=${encodeURIComponent(design.id)}&own=1">${cover(design)}<span class="works-cover-count">${design.published?t('已公开','Shared'):t('私人草稿','Private draft')}</span></a><div class="works-card-body"><h2><a href="./work-detail.html?id=${encodeURIComponent(design.id)}&own=1">${escape(design.name)}</a></h2><p class="work-author">${escape(design.author||t('你','You'))}</p><p class="works-model">${escape(design.model||t('自定义设计','Custom design'))}</p><div class="works-card-actions"><button class="primary" data-print="${escape(design.id)}">${t('去打印','Print')}</button><button class="secondary" data-edit="${escape(design.id)}">${t('去设计','Design')}</button></div></div></article>`).join(''):`<div class="works-empty"><span aria-hidden="true">✿</span><h2>${t('还没有作品','No designs yet')}</h2><p>${t('从一张喜欢的照片开始创作吧。','Start with a photo you love.')}</p><a href="./" class="primary">${t('开始创作','Start designing')} ↗</a></div>`;root.querySelectorAll('[data-edit]').forEach(button=>button.onclick=()=>editDesign(store.list().find(d=>d.id===button.dataset.edit)));root.querySelectorAll('[data-print]').forEach(button=>button.onclick=()=>openPrint(store.list().find(d=>d.id===button.dataset.print)));}
async function editDesign(design){if(!design)return;try{const entry={...design,id:crypto.randomUUID(),designId:design.id};if(!design.flowState&&design.source!=='template'){const image=new Image();image.src=design.image;await image.decode();const canvas=document.createElement('canvas');canvas.width=660;canvas.height=1282;const ctx=canvas.getContext('2d'),scale=Math.max(canvas.width/image.width,canvas.height/image.height),w=image.width*scale,h=image.height*scale,z=Number(design.zoom||100)/100;ctx.drawImage(image,canvas.width/2+((canvas.width-w)/2-canvas.width/2)*z,canvas.height/2+((canvas.height-h)*Number(design.position??50)/100-canvas.height/2)*z,w*z,h*z);entry.backgroundImage=canvas.toDataURL('image/jpeg',.92);}sessionStorage.setItem('popomo-design-entry',JSON.stringify(entry));location.href='./customize.html?entry='+encodeURIComponent(entry.id)+'#design';}catch{notify('暂时无法打开此作品，请重试','Could not open this design. Please retry.');}}
async function openPrint(design){if(!design)return;const button=root.querySelector(`[data-print="${CSS.escape(design.id)}"]`);if(button)button.disabled=true;try{let snapshot={...design};const model=models.find(m=>m.name===design.model);if(!design.cover&&model){const load=async src=>{const image=new Image();image.src=src;await image.decode();return image;};const [image,mask,overlay]=await Promise.all([load(design.image),load(model.mask),load(model.overlay)]);const canvas=document.createElement('canvas');canvas.width=model.width;canvas.height=model.height;const ctx=canvas.getContext('2d'),scale=Math.max(canvas.width/image.width,canvas.height/image.height),z=Number(design.zoom||100)/100,w=image.width*scale*z,h=image.height*scale*z;ctx.drawImage(image,(canvas.width-w)/2,(canvas.height-h)*Number(design.position??50)/100,w,h);ctx.globalCompositeOperation='destination-in';ctx.drawImage(mask,0,0,canvas.width,canvas.height);ctx.globalCompositeOperation='source-over';ctx.drawImage(overlay,0,0,canvas.width,canvas.height);snapshot.cover=canvas.toDataURL('image/webp',.85);}const order=window.PopomoOrders.create(snapshot);location.href='./checkout.html?order='+encodeURIComponent(order.id);}catch{if(button)button.disabled=false;notify('暂时无法创建订单，请重试','Could not create order. Please retry.');}}
document.querySelector('#flow-language').onchange=e=>{language=e.target.value;try{localStorage.setItem('popomo-language',language);}catch{}render();};
render();fetch('./flow-assets/data.json').then(r=>r.json()).then(data=>{models=data.models;render();}).catch(()=>{});
